#!/usr/bin/env python3
"""Build static learning content, browser exercise contracts and slide search index."""
from pathlib import Path
import ast,json,re,subprocess
from html.parser import HTMLParser
ROOT=Path(__file__).resolve().parents[1]
class Plain(HTMLParser):
    def __init__(self): super().__init__();self.parts=[]
    def handle_data(self,x): self.parts.append(x)
def plain(x):
    p=Plain();p.feed(x);return re.sub(r'\s+',' ',' '.join(p.parts)).strip()
def write(name,data):
    (ROOT/f'assets/{name}.js').write_text('/* Generated by scripts/build_learning_data.py */\nconst '+name.upper().replace('-','_')+' = '+json.dumps(data,ensure_ascii=False,indent=2)+';\nif(typeof module!=="undefined")module.exports='+name.upper().replace('-','_')+';\n')
course=json.loads(subprocess.check_output(['node','-e',"process.stdout.write(JSON.stringify(require('./assets/course-data.js')))"],cwd=ROOT))
index=[]
for u in course['units']:
    for i,s in enumerate(json.loads((ROOT/f"authoring/unit{u['id']}-content.json").read_text()),1):
        index.append(dict(unit=u['id'],slide=i,title=plain(s['title']),text=plain(s['body']),notes=s['notes']))
write('search-data',index)
